18	
19	// formatMarker identifies the on-disk file format version.
20	const formatMarker = "edgefleet-heartbeats-v1"
21	
22	// onlineWindow is the maximum age of the latest telemetry for a node to be
23	// considered online. Exactly onlineWindow is still online.
24	const onlineWindow = 60 * time.Second
25	
26	// CorruptError means the on-disk data failed parsing or verification. The
27	// store refuses to read or write while corruption is present.
28	type CorruptError struct {
29		Path string
30		Err  error
31	}
32	
33	func (e *CorruptError) Error() string {
34		return fmt.Sprintf("data corruption detected in %s: %v", e.Path, e.Err)
35	}
36	
37	func (e *CorruptError) Unwrap() error { return e.Err }
38	
39	// IsCorrupt reports whether err is (or wraps) a CorruptError.
40	func IsCorrupt(err error) bool {
41		var ce *CorruptError
42		return errors.As(err, &ce)
43	}
44	
45	// nodeFile is the on-disk layout for one node.
46	type nodeFile struct {
47		Format   string      `json:"format"`
48		Checksum string      `json:"checksum"`
49		Records  []Heartbeat `json:"records"`
50	}
51	
52	// Store persists heartbeats as per-node JSON files under a data directory.
53	// Multiple Store instances (in the same or different processes) may safely
54	// access the same directory concurrently: a flock on the directory lock file
55	// serialises writers and lets queries take a shared lock, so a query never
56	// observes a partially written batch.
57	type Store struct {
58		dir      string
59		nodesDir string
60		lockPath string
61	}
62	
63	// OpenStore opens (and if needed creates) a data directory.
64	func OpenStore(dir string) (*Store, error) {
65		if err := os.MkdirAll(dir, 0o755); err != nil {
66			return nil, fmt.Errorf("cannot create data directory %s: %w", dir, err)
67		}
68		nodesDir := filepath.Join(dir, "nodes")
69		if err := os.MkdirAll(nodesDir, 0o755); err != nil {
70			return nil, fmt.Errorf("cannot create nodes directory %s: %w", nodesDir, err)
71		}
72		return &Store{dir: dir, nodesDir: nodesDir, lockPath: filepath.Join(dir, "lock")}, nil
73	}
74	
75	// Dir returns the data directory path.
76	func (s *Store) Dir() string { return s.dir }
77	
78	// nodePath maps a node id to its per-node file. Hex encoding keeps arbitrary
79	// node ids safe as filenames while remaining reversible.
80	func (s *Store) nodePath(nodeID string) string {
81		return filepath.Join(s.nodesDir, hex.EncodeToString([]byte(nodeID))+".json")
82	}
83	
84	// lock acquires the directory lock. Exclusive for writes, shared for reads.
85	// The returned closure releases the lock.
86	func (s *Store) lock(exclusive bool) (func(), error) {
87		f, err := os.OpenFile(s.lockPath, os.O_RDWR|os.O_CREATE, 0o600)
88		if err != nil {
89			return nil, fmt.Errorf("cannot open lock file %s: %w", s.lockPath, err)
90		}
91		how := syscall.LOCK_SH
92		if exclusive {
93			how = syscall.LOCK_EX
94		}
95		if err := syscall.Flock(int(f.Fd()), how); err != nil {
96			f.Close()
97			return nil, fmt.Errorf("cannot acquire data lock: %w", err)
98		}
99		return func() {
100			syscall.Flock(int(f.Fd()), syscall.LOCK_UN)
101			f.Close()
102		}, nil
103	}
104	
105	// checksumRecords returns a stable hash of the records. json.Marshal of a
106	// struct slice is deterministic for a given set of records.
107	func checksumRecords(records []Heartbeat) string {
108		data, _ := json.Marshal(records)
109		sum := sha256.Sum256(data)
110		return hex.EncodeToString(sum[:])
111	}
112	
113	// nodeIDFromPath recovers the node id a store file belongs to from its file
114	// name: nodePath writes each node's records to hex(nodeID)+".json", so the
115	// owner is exactly the string the base name decodes to. Node ids are compared
116	// as the exact strings they are — ids containing Chinese characters, spaces
117	// or slashes decode back unchanged and are never normalised or merged.
118	func nodeIDFromPath(path string) (string, error) {
119		base := filepath.Base(path)
120		if !strings.HasSuffix(base, ".json") {
121			return "", fmt.Errorf("file name %q is not a per-node heartbeat file", base)
122		}
123		raw, err := hex.DecodeString(strings.TrimSuffix(base, ".json"))
124		if err != nil {
125			return "", fmt.Errorf("file name %q does not encode a node id: %w", base, err)
126		}
127		return string(raw), nil
128	}
129	
130	// loadNodeFile reads and verifies the file for one node. A missing file means
131	// the node has no records (returns nil, nil). Any parse, checksum, ownership
132	// or structural failure is reported as a CorruptError.
133	//
134	// Ownership: the file belongs to exactly one node — the one encoded in its
135	// file name — and every record in it must declare that same node id. A file
136	// whose records name another node (for example another node's file copied
137	// over this one, format and checksum still intact) is not that node's
138	// telemetry: the whole file is refused as corrupt, no matter where the
139	// foreign record sits in the history and even if the latest record happens
140	// to name the right node.
141	//
142	// The file is decoded with the same strict rules as submit input: every
143	// telemetry field must be present, non-null and written once per record. A
144	// checksum that matches the zero-filled interpretation of a tampered record
145	// therefore cannot make a missing value look like real telemetry — the
146	// record is rejected before the checksum is consulted.
147	func loadNodeFile(path string) (*nodeFile, error) {
148		data, err := os.ReadFile(path)
149		if os.IsNotExist(err) {
150			return nil, nil
151		}
152		if err != nil {
153			return nil, &CorruptError{Path: path, Err: err}
154		}
155		nf, err := decodeStrictNodeFile(data)
156		if err != nil {
157			return nil, &CorruptError{Path: path, Err: err}
158		}
159		if nf.Format != formatMarker {
160			return nil, &CorruptError{Path: path, Err: fmt.Errorf("unknown format marker %q", nf.Format)}
161		}
162		if err := validateStoredRecords(nf.Records); err != nil {
163			return nil, &CorruptError{Path: path, Err: err}
164		}
165		if got := checksumRecords(nf.Records); got != nf.Checksum {
166			return nil, &CorruptError{Path: path, Err: fmt.Errorf("checksum mismatch: stored %s, computed %s", nf.Checksum, got)}
167		}
168		owner, err := nodeIDFromPath(path)
169		if err != nil {
170			return nil, &CorruptError{Path: path, Err: err}
171		}
172		for i, r := range nf.Records {
173			if r.NodeID != owner {
174				return nil, &CorruptError{Path: path, Err: fmt.Errorf(
175					"record %d: heartbeat declares node %q, but this file belongs to node %q",
176					i+1, r.NodeID, owner)}
177			}
178		}
179		return nf, nil
180	}
181	
182	// decodeStrictNodeFile parses the on-disk envelope without letting
183	// encoding/json defaults hide missing or duplicated data. The envelope has
184	// exactly three keys — format, checksum, records — each present, non-null and
185	// written once; the uniqueness judgement is the shared objectFields rule, so
186	// a Unicode-escaped spelling of the same key collides exactly as it does in a
187	// submitted heartbeat object. Every element of records is decoded with
188	// decodeStrictHeartbeatObject, so a missing, null or duplicated telemetry
189	// field is an error naming the record and field rather than a zero value.
190	// Whitespace and key ordering carry no meaning and never cause a failure.
191	func decodeStrictNodeFile(data []byte) (*nodeFile, error) {
192		dec := json.NewDecoder(bytes.NewReader(data))
193		tok, err := dec.Token()
194		if err != nil {
195			return nil, fmt.Errorf("invalid JSON: %w", err)
196		}
197		if d, ok := tok.(json.Delim); !ok || d != '{' {
198			return nil, fmt.Errorf("invalid JSON: file must be a JSON object")
199		}
200	
201		var (
202			format   string
203			checksum string
204			records  []json.RawMessage
205		)
206		fields := objectFields{}
207		for dec.More() {
208			keyTok, err := dec.Token()
209			if err != nil {
210				return nil, fmt.Errorf("invalid JSON: %w", err)
211			}
212			key, ok := keyTok.(string)
213			if !ok {
214				return nil, fmt.Errorf("invalid JSON: envelope field name must be a string")
215			}
216			var val json.RawMessage
217			if err := dec.Decode(&val); err != nil {
218				return nil, fmt.Errorf("invalid value for envelope field %q: %w", key, err)
219			}
220			if fields.check(key) {
221				return nil, fmt.Errorf("duplicate envelope field %q", key)
222			}
223			switch key {
224			case "format":
225				if bytes.Equal(val, []byte("null")) {
226					return nil, fmt.Errorf("envelope field %q must not be null", key)
227				}
228				if err := json.Unmarshal(val, &format); err != nil {
229					return nil, fmt.Errorf("format must be a string: %w", err)
230				}
231			case "checksum":
232				if bytes.Equal(val, []byte("null")) {
233					return nil, fmt.Errorf("envelope field %q must not be null", key)
234				}
235				if err := json.Unmarshal(val, &checksum); err != nil {
236					return nil, fmt.Errorf("checksum must be a string: %w", err)
237				}
238			case "records":
239				if bytes.Equal(val, []byte("null")) {
240					return nil, fmt.Errorf("envelope field %q must not be null", key)
241				}
242				if err := json.Unmarshal(val, &records); err != nil {
243					return nil, fmt.Errorf("records must be an array of heartbeat objects: %w", err)
244				}
245			default:
246				return nil, fmt.Errorf("unknown envelope field %q", key)
247			}
248		}
249		// Consume the closing brace.
250		if _, err := dec.Token(); err != nil {
251			return nil, fmt.Errorf("invalid JSON: %w", err)
252		}
253		// Nothing may follow the single envelope object.
254		if _, err := dec.Token(); err != io.EOF {
255			if err == nil {
256				return nil, fmt.Errorf("invalid JSON: unexpected data after the envelope object")
257			}
258			return nil, fmt.Errorf("invalid JSON: %w", err)
259		}
260	
261		if !fields.has("format") {
262			return nil, fmt.Errorf("missing required envelope field %q", "format")
263		}
264		if !fields.has("checksum") {
265			return nil, fmt.Errorf("missing required envelope field %q", "checksum")
266		}
267		if !fields.has("records") {
268			return nil, fmt.Errorf("missing required envelope field %q", "records")
269		}
270	
271		nf := &nodeFile{Format: format, Checksum: checksum, Records: make([]Heartbeat, 0, len(records))}
272		for i, raw := range records {
273			h, err := decodeStrictHeartbeatObject(raw)
274			if err != nil {
275				return nil, fmt.Errorf("record %d: %w", i+1, err)
276			}
277			nf.Records = append(nf.Records, h)
278		}
279		return nf, nil
280	}
281	
282	// validateStoredRecords checks the structural invariants of a strictly
283	// decoded record set: each record must satisfy the same field-value rules as
284	// submit input (one shared rule set — see checkHeartbeatValues), and records
285	// must be sorted by ascending seq with no duplicate seq. The stored-data
286	// wording and 1-based position prefix are kept by storedError. Position
287	// numbers are 1-based to match decoder errors.
288	func validateStoredRecords(records []Heartbeat) error {
289		for i, r := range records {
290			if e := checkHeartbeatValues(r); e != nil {
291				return e.storedError(i + 1)
292			}
293			if i > 0 && records[i-1].Seq >= r.Seq {
294				return fmt.Errorf("records not sorted by ascending seq at record %d", i+1)
295			}
296		}
297		return nil
298	}
299	
300	// writeNodeFile persists records atomically: a temp file in the same
301	// directory is fsynced and renamed over the target, so a crash never leaves
302	// a half-written file.
303	func writeNodeFile(path string, records []Heartbeat) error {
304		if records == nil {
305			records = []Heartbeat{}
306		}
307		nf := nodeFile{
308			Format:   formatMarker,
309			Checksum: checksumRecords(records),
310			Records:  records,
311		}
312		data, err := json.MarshalIndent(nf, "", "  ")
313		if err != nil {
314			return err
315		}
316		return writeFileAtomic(path, data)
317	}
318	
319	func writeFileAtomic(path string, data []byte) error {
320		dir := filepath.Dir(path)
321		tmp, err := os.CreateTemp(dir, ".tmp-*")
322		if err != nil {
323			return err
324		}
325		tmpName := tmp.Name()
326		if _, err := tmp.Write(data); err != nil {
327			tmp.Close()
328			os.Remove(tmpName)
329			return err
330		}
331		if err := tmp.Sync(); err != nil {
332			tmp.Close()
333			os.Remove(tmpName)
334			return err
335		}
336		if err := tmp.Close(); err != nil {
337			os.Remove(tmpName)
338			return err
339		}
340		if err := os.Rename(tmpName, path); err != nil {
341			os.Remove(tmpName)
342			return err
343		}
344		// Best-effort fsync of the directory so the rename itself survives.
345		if d, err := os.Open(dir); err == nil {
346			d.Sync()
347			d.Close()
348		}
349		return nil
350	}
351	
352	// mergeRecord applies the single dedup/conflict rule shared by both submit
353	// phases (records within the batch, and the batch against stored history): a
354	// record's identity is its node id and seq together, and known must contain
355	// only records of that same node. If known already holds the identity, the
356	// incoming record is a duplicate when Heartbeat.Equal says the content is
357	// identical — collection time compared as an instant, node id and version
358	// compared as-is — and a conflict when any field differs. A conflict is an
359	// error naming the node and seq and changes nothing; a duplicate leaves
360	// known untouched and reports dup. Otherwise the record is appended and
361	// returned in the updated slice.
362	func mergeRecord(known []Heartbeat, r Heartbeat) (updated []Heartbeat, dup bool, err error) {
363		for _, e := range known {
364			if e.Seq == r.Seq {
365				if !e.Equal(r) {
366					return nil, false, fmt.Errorf("conflicting record for node %q seq %d: content differs", r.NodeID, r.Seq)
367				}
368				return known, true, nil
369			}
370		}
371		return append(known, r), false, nil
372	}
373	
374	// Submit persists a batch of heartbeats. The whole batch is validated and
375	// checked for duplicates/conflicts against stored data (and within the batch)
376	// before anything is written: a single invalid or conflicting record fails
377	// the batch with no changes. Duplicates are counted, not written. A
378	// successful return means the batch was durably persisted; a persistence
379	// failure is reported and previously queryable data is left intact.
380	func (s *Store) Submit(records []Heartbeat, receiveTime time.Time) (newCount, dupCount int, err error) {
381		if len(records) == 0 {
382			return 0, 0, fmt.Errorf("no heartbeat records provided")
383		}
384		for _, r := range records {
385			if err := ValidateHeartbeat(r, receiveTime); err != nil {
386				return 0, 0, fmt.Errorf("invalid heartbeat for node %q seq %d: %w", r.NodeID, r.Seq, err)
387			}
388		}
389	
390		unlock, err := s.lock(true)
391		if err != nil {
392			return 0, 0, err
393		}
394		defer unlock()
395	
396		// Deduplicate within the batch: same node+seq with equal content counts
397		// as a duplicate; same node+seq with differing content is a conflict.
398		merged := make(map[string][]Heartbeat)
399		for _, r := range records {
400			list, dup, err := mergeRecord(merged[r.NodeID], r)
401			if err != nil {
402				return 0, 0, err
403			}
404			if dup {
405				dupCount++
406				continue
407			}
408			merged[r.NodeID] = list
409		}
410	
411		// Merge with stored data per node, collecting new file contents.
412		type update struct {
413			path    string
414			records []Heartbeat
415		}
416		var updates []update
417		for nodeID, batch := range merged {
418			path := s.nodePath(nodeID)
419			nf, err := loadNodeFile(path)
420			if err != nil {
421				return 0, 0, err
422			}
423			existing := []Heartbeat{}
424			if nf != nil {
425				existing = nf.Records
426			}
427			for _, r := range batch {
428				var dup bool
429				existing, dup, err = mergeRecord(existing, r)
430				if err != nil {
431					return 0, 0, err
432				}
433				if dup {
434					dupCount++
435				} else {
436					newCount++
437				}
438			}
439			sort.Slice(existing, func(i, j int) bool { return existing[i].Seq < existing[j].Seq })
440			updates = append(updates, update{path: path, records: existing})
441		}
442	
443		// Persist. All updates are appends to previously verified data, so a
444		// failure here leaves every previously queryable record intact.
445		for _, u := range updates {
446			if err := writeNodeFile(u.path, u.records); err != nil {
447				return 0, 0, fmt.Errorf("failed to persist heartbeat batch: %w", err)
448			}
449		}
450		return newCount, dupCount, nil
451	}
452	
453	// HealthResult is the health judgement for one node based on real telemetry.
454	type HealthResult struct {
455		NodeID      string
456		Status      string // "online", "offline", "notelemetry"
457		Seq         int64
458		CollectedAt time.Time
459		Version     string
460		Height      int64
461		Missed      int64 // cumulative missed duties at the latest heartbeat
462		Findings    []string
463	
464		// Baseline-relative missed duties, populated only by HealthSince.
465		// BaselineSeq is the seq of the heartbeat the query was anchored to;
466		// BaselineMissed is the cumulative count at that heartbeat. When
467		// NewMissedKnown is false the cumulative counter went backwards
468		// somewhere between the baseline and the latest record, so the number of
469		// newly missed duties cannot be derived; Findings then reports the
470		// rollback. Missed always remains the latest cumulative count.
471		BaselineSeq    int64
472		BaselineMissed int64
473		NewMissed      int64
474		NewMissedKnown bool
475	}
476	
477	// rollbackFinding warns that the cumulative missed-duty counter decreased
478	// between two adjacent saved heartbeats (typically a node counter reset),
479	// which makes the endpoint difference unusable as the new-miss count.
480	const rollbackFinding = "累计漏签数回退"
481	
482	// Health judges a node from its latest telemetry (the record with the
483	// greatest seq). A node with no heartbeats returns Status "notelemetry". A
484	// query time earlier than the record's collection time is an error. Online
485	// status uses collection age against the query time: at most 60s is online
486	// (exactly 60s still online). Version skew and missed-duty rules follow the
487	// existing Evaluate rules.
488	func (s *Store) Health(nodeID string, at time.Time, expectedVersion string, toleratedMisses int) (HealthResult, error) {
489		return s.health(nodeID, at, expectedVersion, toleratedMisses, 0, false)
490	}
491	
492	// HealthSince judges a node the same way Health does, but the missed-duty
493	// alarm is measured against a user-supplied baseline heartbeat instead of the
494	// cumulative counter alone. baselineSeq must be the seq (> 0) of a record
495	// already saved for the node: the latest heartbeat stays the record with the
496	// greatest seq, and new missed duties are the latest cumulative count minus
497	// the count at the baseline record. Only a strict excess over
498	// toleratedMisses alarms; equality does not.
499	//
500	// The baseline affects this query only: stored history is never modified.
501	// Seqs between the baseline and the latest may have gaps. If the cumulative
502	// count decreases between any two adjacent saved records in that interval the
503	// new count is reported as unknown (NewMissedKnown == false) and a rollback
504	// finding is emitted, even if the latest count later climbs back past the
505	// baseline; decreases before the baseline are irrelevant. A node without
506	// telemetry, an unknown baseline seq, or a baseline newer than the latest
507	// record is an error — no other record is substituted and the baseline count
508	// is never assumed to be zero.
509	func (s *Store) HealthSince(nodeID string, at time.Time, expectedVersion string, toleratedMisses int, baselineSeq int64) (HealthResult, error) {
510		if baselineSeq <= 0 {
511			return HealthResult{}, fmt.Errorf("--missed-since-seq must be a positive integer, got %d", baselineSeq)
512		}
513		return s.health(nodeID, at, expectedVersion, toleratedMisses, baselineSeq, true)
514	}
515	
516	func (s *Store) health(nodeID string, at time.Time, expectedVersion string, toleratedMisses int, baselineSeq int64, useBaseline bool) (HealthResult, error) {
517		unlock, err := s.lock(false)
518		if err != nil {
519			return HealthResult{}, err
520		}
521		defer unlock()
522	
523		nf, err := loadNodeFile(s.nodePath(nodeID))
524		if err != nil {
525			return HealthResult{}, err
526		}
527		if nf == nil || len(nf.Records) == 0 {
528			if useBaseline {
529				return HealthResult{}, fmt.Errorf("node %q has no heartbeats; cannot use --missed-since-seq=%d as baseline", nodeID, baselineSeq)
530			}
531			return HealthResult{NodeID: nodeID, Status: "notelemetry", Findings: []string{"无遥测"}}, nil
532		}
533	
534		records := nf.Records // ascending seq, unique
535		latest := records[len(records)-1]
536	
537		if useBaseline {
538			if baselineSeq > latest.Seq {
539				return HealthResult{}, fmt.Errorf("--missed-since-seq=%d is newer than the latest heartbeat seq %d for node %q", baselineSeq, latest.Seq, nodeID)
540			}
541		}
542	
543		if at.Before(latest.CollectedAt) {
544			return HealthResult{}, fmt.Errorf("query time %s is earlier than collection time %s for node %q",
545				at.Format(time.RFC3339), latest.CollectedAt.Format(time.RFC3339), nodeID)
546		}
547	
548		age := at.Sub(latest.CollectedAt)
549		online := age <= onlineWindow
550	
551		result := HealthResult{
552			NodeID:      nodeID,
553			Status:      "online",
554			Seq:         latest.Seq,
555			CollectedAt: latest.CollectedAt,
556			Version:     latest.Version,
557			Height:      latest.Height,
558			Missed:      latest.Missed,
559		}
560		if !online {
561			result.Status = "offline"
562		}
563	
564		if !useBaseline {
565			// Cumulative judgement: the current counter must strictly exceed the
566			// tolerance. Evaluate holds this rule — and the shared online/version
567			// rules — in exactly one place for the demo and both query paths.
568			node := Node{
569				ID:      nodeID,
570				Version: latest.Version,
571				Height:  latest.Height,
572				Missed:  int(latest.Missed),
573				Online:  online,
574			}
575			result.Findings = Evaluate(node, expectedVersion, toleratedMisses).Findings
576			return result, nil
577		}
578	
579		// Baseline judgement: the online and version-skew findings come from the
580		// same shared rules as the cumulative query above; only the missed-duty
581		// statistic differs — it counts duties missed after the baseline record
582		// instead of the latest cumulative total.
583		findings := append([]string{}, livenessVersionFindings(online, latest.Version, expectedVersion)...)
584	
585		baselineIdx := -1
586		for i, r := range records {
587			if r.Seq == baselineSeq {
588				baselineIdx = i
589				break
590			}
591		}
592		if baselineIdx < 0 {
593			return HealthResult{}, fmt.Errorf("no saved heartbeat with seq %d for node %q; cannot use it as --missed-since-seq baseline", baselineSeq, nodeID)
594		}
595		baseline := records[baselineIdx]
596		result.BaselineSeq = baseline.Seq
597		result.BaselineMissed = baseline.Missed
598	
599		// Walk only saved records from the baseline up to the latest. Records are
600		// stored ascending by seq and seqs may legitimately have gaps, so any
601		// decrease between two adjacent saved records in this interval proves the
602		// cumulative counter reset somewhere in it; the endpoint difference alone
603		// must not be trusted even if the final count recovers.
604		rolledBack := false
605		for i := baselineIdx + 1; i < len(records); i++ {
606			if records[i].Missed < records[i-1].Missed {
607				rolledBack = true
608				break
609			}
610		}
611		if rolledBack {
612			result.NewMissedKnown = false
613			findings = append(findings, rollbackFinding)
614		} else {
615			result.NewMissedKnown = true
616			// No decrease was observed, so cumulative counts cannot have wrapped
617			// backwards within int64 range; the difference stays exact.
618			result.NewMissed = latest.Missed - baseline.Missed
619			if result.NewMissed > int64(toleratedMisses) {
620				findings = append(findings, missedAboveToleranceFinding)
621			}
622		}
623		result.Findings = findings
624		return result, nil
625	}
626	
627	// History returns all heartbeats for a node in ascending seq order, without
628	// duplicates. A node with no records returns an empty slice.
629	func (s *Store) History(nodeID string) ([]Heartbeat, error) {
630		unlock, err := s.lock(false)
631		if err != nil {
632			return nil, err
633		}
634		defer unlock()
635	
636		nf, err := loadNodeFile(s.nodePath(nodeID))
637		if err != nil {
638			return nil, err
639		}
640		if nf == nil {
641			return []Heartbeat{}, nil
642		}
643		return nf.Records, nil
644	}
645

