69	// seedReconnectStored stores the disordered pair in the "natural outage"
70	// arrival order: the stale seq-10 record was received during the outage
71	// (90 seconds after it was collected), and the fresh seq-5 record is only
72	// backfilled when the node reconnects at the query instant.
73	func seedReconnectStored(t *testing.T, dir string) {
74		t.Helper()
75		submitWithReceive(t, dir, "["+reconnectStaleRecord+"]", reconnectStaleReceive)
76		submitWithReceive(t, dir, "["+reconnectFreshRecord+"]", cliReceiveAt)
77	}
