79	// seedReconnectReversed stores the same pair with the stale greatest-seq
80	// record physically arriving after the fresh smaller-seq record.
81	func seedReconnectReversed(t *testing.T, dir string) {
82		t.Helper()
83		submitWithReceive(t, dir, "["+reconnectFreshRecord+"]", cliReceiveAt)
84		submitWithReceive(t, dir, "["+reconnectStaleRecord+"]", cliReceiveAt)
85	}
