147	// TestCLIHealthLateDuplicateResubmitChangesNothing replays the smaller-seq
148	// record at a later receive time, first already covered by the stored pair
149	// via a fresh backfill, then as a verbatim duplicate, and checks the latest
150	// telemetry collection time and the offline judgement never move.
151	func TestCLIHealthLateDuplicateResubmitChangesNothing(t *testing.T) {
152		dir := t.TempDir()
153		// Only the stale greatest-seq record is known initially.
154		submitWithReceive(t, dir, "["+reconnectStaleRecord+"]", reconnectStaleReceive)
155	
156		out, _, code := healthQueryAt(t, dir, cliQueryAt,
157			"--node", reconnectNode, "--expected-version", "1.26.0", "--tolerated-misses", "4")
158		if code != 0 || !strings.Contains(out, "seq=10") || !strings.Contains(out, "status=offline") {
159			t.Fatalf("initial query: code=%d out=%q", code, out)
160		}
161	
162		// The node reconnects later and backfills the smaller seq for the first
163		// time. Its receive time is later, but the latest record stays seq 10.
164		later := "2026-10-01T12:02:00Z"
165		submitOut, errOut, submitCode := runCLI(t, dir, "["+reconnectFreshRecord+"]",
166			"heartbeat", "submit", "--data-dir", dir, "--receive-time", later)
167		if submitCode != 0 {
168			t.Fatalf("late backfill exited %d: stderr=%q stdout=%q", submitCode, errOut, submitOut)
169		}
170		if !strings.Contains(submitOut, "new=1 duplicate=0") {
171			t.Errorf("first backfill counts = %q, want new=1 duplicate=0", strings.TrimSpace(submitOut))
172		}
173		out, _, code = healthQueryAt(t, dir, later,
174			"--node", reconnectNode, "--expected-version", "1.26.0", "--tolerated-misses", "4")
175		assertReconnectHealthLineLater(t, out, code, later)
176	
177		// Re-submitting the same record at yet another receive time is a duplicate
178		// and must not refresh the latest collection time or change any judgement.
179		evenLater := "2026-10-01T12:03:00Z"
180		submitOut, _, submitCode = runCLI(t, dir, "["+reconnectFreshRecord+"]",
181			"heartbeat", "submit", "--data-dir", dir, "--receive-time", evenLater)
182		if submitCode != 0 {
183			t.Fatalf("duplicate replay exited %d: stderr=%q", submitCode, errOut)
184		}
185		if !strings.Contains(submitOut, "new=0 duplicate=1") {
186			t.Errorf("duplicate replay counts = %q, want new=0 duplicate=1", strings.TrimSpace(submitOut))
187		}
188		out, _, code = healthQueryAt(t, dir, evenLater,
189			"--node", reconnectNode, "--expected-version", "1.26.0", "--tolerated-misses", "4")
190		assertReconnectHealthLineLater(t, out, code, evenLater)
191	}
