61	// runCLI invokes the re-executed binary with the given arguments. stdin is
62	// fed to the command (used by `heartbeat submit`). It returns the captured
63	// stdout, stderr and exit code.
64	func runCLI(t *testing.T, dir, stdin string, args ...string) (string, string, int) {
65		t.Helper()
66		cmd := exec.Command(os.Args[0], args...)
67		cmd.Stdin = strings.NewReader(stdin)
68		// Keep HOME inside the temp area too, so a missing --data-dir could never
69		// touch the developer's real ~/.edgefleet.
70		cmd.Env = append(os.Environ(),
71			cliTestEnv+"=1",
72			"HOME="+dir,
73			"EDGEFLEET_DATA_DIR="+filepath.Join(dir, "env-data"),
74		)
75		var out, errOut strings.Builder
76		cmd.Stdout = &out
77		cmd.Stderr = &errOut
78		err := cmd.Run()
79		code := 0
80		if err != nil {
81			var exitErr *exec.ExitError
82			if errors.As(err, &exitErr) {
83				code = exitErr.ExitCode()
84			} else {
85				t.Fatalf("failed to run helper binary: %v", err)
86			}
87		}
88		return out.String(), errOut.String(), code
89	}
