118	// newFixture creates a temp data directory with three nodes:
119	//
120	//	mono:   seq 1/2/3, cumulative missed 12/13/14, version 1.26.0
121	//	reset:  seq 1/2/3, cumulative missed 12/5/14 (counter reset), version 1.25.0
122	//	gappy:  seq 1/3 (seq 2 never saved), missed 0/4, version 1.26.0
123	//
124	// Latest collection time is one second before cliQueryAt, so every node is
125	// online at the query instant.
126	func newFixture(t *testing.T) *fixture {
127		t.Helper()
