147	func TestCLIHealthBaselineTakesEffect(t *testing.T) {
148		f := newFixture(t)
149	
150		// Baseline cumulative 12, latest cumulative 14, tolerance 2: the two new
151		// missed duties equal the tolerance and must NOT alarm.
152		out, errOut, code := health(t, f,
153			"--node", "mono", "--expected-version", "1.26.0",
154			"--tolerated-misses", "2", "--missed-since-seq", "1")
155		if code != 0 {
156			t.Fatalf("health query with a valid baseline must succeed, exit=%d stderr=%q", code, errOut)
157		}
158		if errOut != "" {
159			t.Errorf("health findings belong on stdout; stderr should be empty, got %q", errOut)
160		}
161	
162		lines := outputLines(out)
163		if len(lines) != 2 {
164			t.Fatalf("baseline query must print two lines, got %d: %q", len(lines), out)
165		}
166	
167		// The latest heartbeat (greatest seq) is still what the first line shows,
168		// and missed there stays the cumulative value (14), never the new count.
169		first := lines[0]
170		for _, want := range []string{
171			"node=mono", "status=online", "seq=3", "version=1.26.0",
172			"height=103", "missed=14", "collected_at=2026-10-01T11:59:59Z",
173		} {
174			if !strings.Contains(first, want) {
175				t.Errorf("first line %q missing %q", first, want)
