185		// The baseline basis is stated separately on the second line.
186		wantSecond := "baseline_seq=1 baseline_missed=12 new_missed=2 tolerated_misses=2"
187		if lines[1] != wantSecond {
188			t.Errorf("second line = %q, want %q", lines[1], wantSecond)
189		}
